changeSet.sql:
ALTER TABLE transactions ADD COLUMN schedule_version integer NOT NULL DEFAULT 1;
COMMENT ON COLUMN transactions.schedule_version IS
    'Phase 5c: the version of transaction_instalments in force. A restructure adds version n+1 and moves this; earlier versions stay as history.';
ALTER TABLE transaction_instalments
    ADD COLUMN carried_penalty numeric(19, 2) NOT NULL DEFAULT 0,
    ADD CONSTRAINT chk_transaction_instalments_carried CHECK (carried_penalty >= 0);
COMMENT ON COLUMN transaction_instalments.carried_penalty IS
    'Phase 5c: penalties reached before a restructure, charged with this instalment (the first new one). Zero otherwise.';

changeSet.rollback:
ALTER TABLE transaction_instalments DROP CONSTRAINT chk_transaction_instalments_carried,
    DROP COLUMN carried_penalty;
ALTER TABLE transactions DROP COLUMN schedule_version;
